<template><view :class="['page issue-policy-page', darkMode ? 'dark-mode' : '', `font-${fontSize}`]"><view class="settings-nav ip-nav"><button class="back-button" aria-label="返回" @click="back"><text class="back-symbol"></text></button></view><text class="ip-heading">政策自查</text><text class="ip-muted">匿名逐题选择，核对条件与官方依据。结果供准备申请参考，以经办部门审核为准。</text><text v-if="loading" class="ip-muted" role="status">正在加载政策…</text><text v-if="error" class="ip-error">{{ error }}</text><button v-if="error" class="ip-button" @click="load">重新加载</button><view v-for="item in items" :key="item.policy_key" class="ip-card"><text class="ip-muted">{{ item.region }}</text><text class="ip-title">{{ item.title }}</text><text class="ip-body">{{ item.summary }}</text><text class="ip-muted">{{ item.available ? '可进行自查' : item.unavailable_reason || '暂不可自查' }}</text><button class="ip-button primary" @click="open(item.policy_key)">查看条件与依据</button></view><text v-if="!loading && !error && !items.length" class="ip-muted">暂无已核验的政策。</text></view></template>
<script>
import { getPolicyChecks } from '@/utils/api.js'
export default { data: () => ({ items: [], loading: false, error: '', darkMode: false, fontSize: 'standard' }), onShow() { this.darkMode = !!uni.getStorageSync('jianwen_dark_mode'); this.fontSize = uni.getStorageSync('jianwen_font_size') || 'standard'; this.load() }, methods: { back() { const fallback = () => uni.switchTab({ url: '/pages/discover/discover' }); if (getCurrentPages().length > 1) uni.navigateBack({ fail: fallback }); else fallback() }, open(key) { uni.navigateTo({ url: `/pages/policy/detail?key=${encodeURIComponent(key)}` }) }, async load() { this.loading = true; this.error = ''; try { this.items = await getPolicyChecks() } catch (e) { this.error = e.message } finally { this.loading = false } } } }
</script>
<style src="../../styles/issue-policy.css"></style>
